const { BigNumber } = require('bignumber.js'); // Importing BigNumber library for arbitrary precision arithmetic

module.exports.main = async function({ REMAINDERS, MODULI }) {
    const n = REMAINDERS.length;
    let x = new BigNumber(0);
    let modulusProduct = new BigNumber(MODULI.reduce((a, b) => a * b));

    for (let i = 0; i < n; i++) {
        const r_i = new BigNumber(REMAINDERS[i]);
        const m_i = new BigNumber(MODULI[i]);
        const M_i_inv = modulusProduct.dividedBy(m_i).invm(m_i);

        x = x.plus(r_i.multipliedBy(M_i_inv).multipliedBy(modulusProduct.dividedBy(m_i)));
    }

    while (x.compare(0) < 0) {
        x = x.plus(modulusProduct);
    }

    return x.mod(modulusProduct).toFixed(0, 1);
};", "name": "Chinese_Remainder"}
