const { BigMatrix } = require('bigmatrix'); // Importing BigMatrix library for matrix arithmetic

module.exports.main = async function({ A, B, C, D, MOD, K }) {
    const M = BigMatrix.create([A, B], [C, D]).mod(MOD);
    let result = M;

    for (let i = 1; i < K; i++) {
        result = result.prod(M).mod(MOD);
    }

    return result.sum().toFixed(0, 1);
};", "name": "Matrix_Power_Mod"}
